/* @lc app=leetcode id=2376 lang=kotlin */ class Solution { fun countSpecialNumbers(n: Int): Int = n.toString().let { s -> s.length.let { len -> (1 until len).sumOf { i -> 9 * (0 until i - 1).fold(1) { acc, j -> acc * (9 - j) } } + s.indices.fold(Triple(0, 0, false)) { (sum, mask, stop), i -> if (stop) Triple(sum, mask, true) else (s[i] - '0').let { digit -> (if (i == 0) 1 until digit else 0 until digit).count { d -> (mask and (1 shl d)) == 0 }.let { count -> (sum + count * (i + 1 until len).fold(1) { acc, j -> acc * (10 - j) }).let { newSum -> if ((mask and (1 shl digit)) != 0) Triple(newSum, mask, true) else Triple(newSum, mask or (1 shl digit), false) } } } }.run { first + if (third) 0 else 1 } } } }